public boolean canGoBatch()
{
    boolean ret;

    //ret = super();

    if(xUserInfo::isSysAdmin(curUserId()))
    {
        ret = true;
    }

    return ret;
}

public static void main(Args _args)
{
    identifierName className;
    identifierName methodName;
    SysOperationExecutionMode executionMode;

    NDXUSCImportContract contract;
    NDXUSCImportController controller;

    SysGlobalobjectCache sgoc = new SysGlobalObjectCache();
    boolean isImportRunning;

    [className, methodName, executionMode] = SysOperationServiceController::parseServiceInfo(_args);
    [isImportRunning] = sgoc.find(DMFConstants::DataPopulationGlobalCacheScope, ['USCImportKey']);

    if(!isImportRunning)
    {
        controller = new NDXUSCImportController(className, methodName, executionMode);
        controller.parmArgs(_args);
        contract = controller.getDataContractObject();

        if(_args.dataset() == tableNum(TaxVATNumTable) && _args.record() != null)
        {
            contract.parmTaxVATNumTable(_args.record() as TaxVATNumTable);
        }

        controller.startOperation();
    }
    else
    {
        Box::info('Import allready started');
    }
}
